CREATE DATABASE IF NOT EXISTS lithography_control;
USE lithography_control;
CREATE TABLE IF NOT EXISTS schema_migrations(version BIGINT PRIMARY KEY,name VARCHAR(255) NOT NULL,applied_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS machines(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(128) NOT NULL UNIQUE,mode ENUM('simulation','authorized_hardware') NOT NULL DEFAULT 'simulation',state VARCHAR(32) NOT NULL DEFAULT 'Offline',created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS sensors(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,machine_id BIGINT UNSIGNED NOT NULL,name VARCHAR(128) NOT NULL,unit VARCHAR(32),enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),UNIQUE KEY uq_sensor_machine_name(machine_id,name),CONSTRAINT fk_sensor_machine FOREIGN KEY(machine_id) REFERENCES machines(id));
CREATE TABLE IF NOT EXISTS sensor_readings(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,sensor_id BIGINT UNSIGNED NOT NULL,value DOUBLE NOT NULL,recorded_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX ix_sensor_time(sensor_id,recorded_at),CONSTRAINT fk_reading_sensor FOREIGN KEY(sensor_id) REFERENCES sensors(id));
CREATE TABLE IF NOT EXISTS alarms(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,machine_id BIGINT UNSIGNED NOT NULL,code VARCHAR(128) NOT NULL,severity ENUM('info','warning','critical') NOT NULL,message VARCHAR(512) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),cleared_at TIMESTAMP(6) NULL,INDEX ix_alarm_machine_active(machine_id,active),CONSTRAINT fk_alarm_machine FOREIGN KEY(machine_id) REFERENCES machines(id));
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,actor VARCHAR(128) NOT NULL,action VARCHAR(128) NOT NULL,target VARCHAR(256) NOT NULL,details JSON NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX ix_audit_time(created_at));
